const { createYoga, createSchema } = require('graphql-yoga');
const { createServer } = require('node:http');
const { GraphQLError } = require('graphql');
const { pool } = require('../database/pg');

const typeDefs = `
  type EmployeePayroll @key(fields: "id") {
    id: ID!
    employeeId: String!
    baseSalary: Float!
    directDepositRouting: String!
    directDepositAccount: String!
    taxWithholdings: Float!
  }

  type Query {
    _dummy: String
  }
`;

const resolvers = {
  EmployeePayroll: {
    __resolveReference: async (reference, context) => {
      if (!context.user) {
        throw new GraphQLError('Authentication required', { extensions: { code: 'UNAUTHENTICATED' } });
      }

      // Query scoped strictly to the employee's tenant and authorization boundaries
      const { rows } = await pool.query(
        'SELECT * FROM employee_payrolls WHERE id = $1 AND tenant_id = $2',
        [reference.id, context.user.tenantId]
      );

      const payroll = rows[0];
      if (!payroll) {
        throw new GraphQLError('Payroll record not found or access denied', {
          extensions: { code: 'NOT_FOUND' }
        });
      }

      const isSelf = payroll.employee_id === context.user.employeeId;
      const isHrAdmin = context.user.roles && context.user.roles.includes('HR_ADMIN');
      if (!isSelf && !isHrAdmin) {
        throw new GraphQLError('Unauthorized access to payroll entity', {
          extensions: { code: 'FORBIDDEN' }
        });
      }

      return payroll;
    }
  }
};

const yoga = createYoga({
  schema: createSchema({ typeDefs, resolvers }),
  context: ({ req }) => ({
    user: req.user,
    headers: req.headers
  })
});

const server = createServer(yoga);
server.listen(4001, () => console.log('Payroll Subgraph running on :4001'));
